// План specs/admin-plans.md 4.2 (кейс AP-13). Только чтение под «בדיקה» (auth/user.json). @prod-safe
// Базовое состояние после истечения выдачи 19.10 (проверено 20.10, скрины r3c-1…3): Techory Lite, без AI и Inventory, без «Granted by Techory».
// Не запускать одновременно с тестами @writes этой фичи (они временно выдают тариф этому же аккаунту).
import { test, expect } from '@playwright/test';
import { setLanguage } from './plans-helpers';
import {
  menuLink, expectMenuLoaded, openBilling, anyGrantedBadge, AI_BLOCKED_TITLE, blockStripe,
} from './plans-read-helpers';

test.use({ storageState: '../auth/user.json' });

test.describe('Admin Panel — Plans: active plan for the user', () => {
  test('User without an active grant is on Techory Lite: no AI or Inventory, AI workspace blocked, no Granted badge #2b3784 #b42657 @desktop @prod-safe', async ({ page }) => {
    await setLanguage(page, 'en');
    const stripeHits = await blockStripe(page);

    // 1. Меню: нет AI и Inventory (источник: тикет — после срока аккаунт сам возвращается на свой план; Lite без AI/склада)
    await page.goto('/dashboard');
    await expectMenuLoaded(page);
    await expect(menuLink(page, 'AI')).toHaveCount(0);
    await expect(menuLink(page, 'Inventory')).toHaveCount(0);

    // 2. /aiworkspace напрямую — экран блокировки с текущим планом
    await page.goto('/aiworkspace');
    await expect(page.getByText(AI_BLOCKED_TITLE, { exact: true })).toBeVisible({ timeout: 30_000 });
    await expect(page.getByText('Current plan: Techory Lite', { exact: true })).toBeVisible();

    // 3. Billing: Techory Lite, бейджа выдачи нет
    await openBilling(page);
    await expect(page.getByText('Techory Lite', { exact: true }).first()).toBeVisible();
    await expect(anyGrantedBadge(page)).toHaveCount(0);

    expect(stripeHits, 'Stripe не должен открываться').toEqual([]);
  });
});
